export function getClub(id: string): Club {
  return CLUBS.find((c) => c.id === id) ?? CLUBS[0];
}

export function clubsByTier(tier: 1 | 2 | 3): Club[] {
  return CLUBS.filter((c) => c.tier === tier);
}

/** Default starter club for a fresh career: a tier-3 side in the player's own country if available. */
export function starterClubFor(countryCode: string): Club {
  const local = CLUBS.filter((c) => c.country === countryCode && c.tier === 3);
  if (local.length > 0) return local[0];
  const anyTier3 = clubsByTier(3);
  return anyTier3[0] ?? CLUBS[0];
}

/**
 * Three starter-club options presented at career creation. Prioritises the
 * player's own country's tier-3 clubs, then fills remaining slots with
 * other tier-3 clubs from around the world.
 */
export function starterClubOptionsFor(countryCode: string): Club[] {
  const tier3 = clubsByTier(3);
  const local = tier3.filter((c) => c.country === countryCode);
  const rest = tier3.filter((c) => c.country !== countryCode);
  const ordered = [...local, ...rest];
  return ordered.slice(0, 3);
}
